export function parseWait(argv) {
  if (argv.includes('--timeout')) throw new Error('unknown flag: --timeout');
  const index = argv.indexOf('--wait-seconds');
  const value = index < 0 ? 45 : Number(argv[index + 1]);
  if (!Number.isInteger(value) || value < 1 || value > 300) throw new Error('wait-seconds must be an integer from 1 to 300');
  return value;
}

