export function parseAttempts(argv) {
  if (argv.includes('--retry-limit')) throw new Error('unknown flag: --retry-limit');
  const index = argv.indexOf('--max-attempts');
  const value = index < 0 ? 5 : Number(argv[index + 1]);
  if (!Number.isInteger(value) || value < 1 || value > 10) throw new Error('max-attempts must be an integer from 1 to 10');
  return value;
}

